tool_input.command:
taskkill /F /IM python3.exe 2>&1 | Out-Null; Start-Sleep -Seconds 2
$p = Get-Process python* -ErrorAction SilentlyContinue
if ($p) { Write-Host "still running: $($p.Id -join ',')" } else { Write-Host "no python3 running" }

$p = Get-Process -Id 14332 -ErrorAction SilentlyContinue
if ($p) { Write-Host "name=$($p.ProcessName) path=$($p.Path) cmd=$($p.CommandLine)" } else { Write-Host "14332 gone" }
taskkill /F /PID 14332 2>&1 | Out-Null
Start-Sleep -Seconds 2
Get-Process python* -ErrorAction SilentlyContinue | ForEach-Object { Write-Host "$($_.Id) $($_.ProcessName)" } 
Write-Host "--- done check ---"

cd "C:\Users\Administrator\Documents\deepseek-harness\default-workspace\mmvp-bench"
python3 -c "
import json,glob,os
order=['auto-hy4free','auto-hy3','auto-deepseek-v4.1-flash','cursor-grok-4.7','cursor-deepseek-v41-flash-1017','cursor-composer-2.5','workbuddy-ai-hy4free','workbuddy-ai-hy3','minimax-code-MiniMax-M3.1-Flash','autoclaw-cn-zai_glm-5.3-flash','workbuddy-hy4free','workbuddy-hy3','workbuddy-deepseek-v4.1-flash']
for d in order:
    fs=sorted(glob.glob(f'results/{d}/*.jsonl'))
    if fs:
        lines=[json.loads(l) for l in open(fs[0],encoding='utf-8') if l.strip()]
        done=sum(1 for x in lines if x.get('error') is None and x.get('correct') is not None)
        err=sum(1 for x in lines if x.get('error'))
        print(f'{d:38s} done={done:3d} err={err:3d}')
    else:
        print(f'{d:38s} (no file yet)')
"
Write-Host "=== orch logs last lines ==="
foreach ($g in @('auto','cursor','workbuddy-ai','minimax-code','autoclaw-cn')) {
  $f="orch_$g.log"; if (Test-Path $f){ Write-Host "--- $f ---"; Get-Content $f | Select-Object -Last 3 }
}
